insert into public.learning_cards (lesson_id, position, title, blocks) values ('008c32e8-3a1f-52c1-93d3-a5c6264102d7', 1, 'Une culture née à New York', '[{"type":"text","text":"Le hip-hop naît dans les années 1970 dans le Bronx. Il réunit quatre disciplines : le rap, le DJing, la danse et le graffiti."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('008c32e8-3a1f-52c1-93d3-a5c6264102d7', 2, 'H.I.P. H.O.P. sur TF1', '[{"type":"keyfigure","value":"1984","label":"Diffusion de l’émission H.I.P. H.O.P. sur TF1"},{"type":"text","text":"Présentée par Sidney, premier animateur noir d’une émission nationale, elle fait découvrir le breakdance à toute une génération."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('008c32e8-3a1f-52c1-93d3-a5c6264102d7', 3, 'Les premiers disques', '[{"type":"list","items":["1984 : Paname City Rappin’, du DJ Dee Nasty, premier album de rap français.","1990 : la compilation Rapattitude fait entendre une nouvelle scène."]}]'::jsonb);
