insert into public.learning_cards (lesson_id, position, title, blocks) values ('87f08a60-b41f-5450-a1ed-7b19eac38602', 2, 'IAM', '[{"type":"text","text":"Le groupe marseillais d’Akhenaton et Shurik’n signe Je danse le Mia (1994), puis L’École du micro d’argent (1997), vendu à plus d’un million d’exemplaires."}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('87f08a60-b41f-5450-a1ed-7b19eac38602', 3, 'NTM', '[{"type":"text","text":"JoeyStarr et Kool Shen, venus de Seine-Saint-Denis, imposent un rap brut : Paris sous les bombes (1995), Laisse pas traîner ton fils (1998)."}]'::jsonb);
