insert into public.learning_cards (lesson_id, position, title, blocks) values ('98c59e1c-2dc5-503c-8a73-0efbce64315b', 1, 'Les mots du rap', '[{"type":"list","items":["Featuring : un morceau avec un artiste invité.","Punchline : une phrase choc.","Freestyle : une improvisation.","Beatmaker : celui qui compose la musique.","Egotrip : le rappeur vante sa réussite.","Verlan : l’inversion des syllabes (« relou » pour « lourd »)."]}]'::jsonb);
insert into public.learning_cards (lesson_id, position, title, blocks) values ('98c59e1c-2dc5-503c-8a73-0efbce64315b', 2, 'Clash et drill', '[{"type":"text","text":"Le clash, morceau où un rappeur en attaque un autre, existe depuis les débuts. La drill, née à Chicago et popularisée à Londres, arrive en France à la fin des années 2010."}]'::jsonb);
